<?php /** Read-only part shared by the tasks of all components. @var string $report @var array $links @var list<int> $docIds */
$report = trim((string)($report ?? '')); $links = (array)($links ?? []); $docs = \Sysfera\Attach::items('docs', (array)($docIds ?? [])); $files = \Sysfera\Attach::items('files', (array)($fileIds ?? [])); ?>
<?php if ($report !== ''): ?><div class="att-blk"><h4><?= e(t('att.report')) ?></h4><p><?= nl2br(e($report)) ?></p></div><?php endif; ?>
<?php if ($links): ?><div class="att-blk"><h4><?= e(t('att.links')) ?></h4><ul class="att-ul"><?php foreach ($links as $l): ?><li><a href="<?= e($l['url']) ?>" target="_blank" rel="noopener noreferrer nofollow"><?= e(($l['title'] ?? '') !== '' ? $l['title'] : $l['url']) ?></a><?php if (($l['title'] ?? '') !== ''): ?> <small class="muted"><?= e(parse_url($l['url'], PHP_URL_HOST) ?: '') ?></small><?php endif; ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<?php if ($docs): ?><div class="att-blk"><h4><?= e(t('att.docs')) ?></h4><div class="att-chips"><?php foreach ($docs as $d): ?><span class="att-chip"><a href="<?= e($d['url']) ?>"><?= e($d['label']) ?></a></span><?php endforeach; ?></div></div><?php endif; ?>
<?php if ($files): ?><div class="att-blk"><h4><?= e(t('att.files')) ?></h4><div class="att-chips"><?php foreach ($files as $d): ?><span class="att-chip"><a href="<?= e($d['url']) ?>"><?= e($d['label']) ?></a></span><?php endforeach; ?></div></div><?php endif; ?>
